// Valida o corpo do pedido e garante que o saldo e numero antes de qualquer comparacao.
const entrada = $input.first().json;
const corpo = entrada.body ?? entrada;
const brutos = corpo.clientes;

if (!Array.isArray(brutos) || brutos.length === 0) {
  throw new Error('Corpo do pedido sem a lista "clientes".');
}

// 'R$ 12.500,00' -> 12500. Em pt-BR o ponto e milhar e a virgula e decimal, ao
// contrario do que Number() espera: sem isto, 'R$ 850,00' viraria 85000 e
// 'R$ 12.500,00' viraria 12.5, e a comparacao com o minimo do produto fica errada.
function saldoParaNumero(valor) {
  if (typeof valor === 'number' && Number.isFinite(valor)) return valor;
  const limpo = String(valor ?? '').replace(/[^\d,.]/g, '').replace(/\./g, '').replace(',', '.');
  const numero = Number.parseFloat(limpo);
  if (!Number.isFinite(numero)) throw new Error(`Saldo ilegivel: ${JSON.stringify(valor)}`);
  return numero;
}

const clientes = brutos.map((c) => ({
  nome: String(c.nome ?? '').trim(),
  email: String(c.email ?? '').trim(),
  perfil: String(c.perfil ?? '').trim(),
  saldo_texto: c.saldo_texto ?? String(c.saldo ?? ''),
  saldo: saldoParaNumero(c.saldo ?? c.saldo_texto),
}));

const incompletos = clientes.filter((c) => !c.nome || !c.perfil);
if (incompletos.length > 0) {
  throw new Error(`${incompletos.length} cliente(s) sem nome ou sem perfil.`);
}

// Um unico item ate ao cruzamento: assim o CSV e buscado uma vez, nao uma por cliente.
return [{ json: { clientes, usar_ia: corpo.usar_ia === true, recebidos: clientes.length } }];

// Le o CSV de investimentos e cruza com os clientes, filtrando pelo saldo.
const csv = $json.csv ?? '';
const linhas = csv.trim().split(/\r?\n/);
if (linhas.length < 2) throw new Error('CSV de investimentos vazio ou sem linhas de dados.');

const cabecalho = linhas.shift().split(',').map((h) => h.trim());
const produtos = linhas
  .filter((l) => l.trim() !== '')
  .map((linha) => {
    const campos = linha.split(',').map((v) => v.trim());
    const p = {};
    cabecalho.forEach((h, i) => { p[h] = campos[i]; });
    p.minimo = Number.parseFloat(p.minimo);
    return p;
  });

const { clientes, usar_ia } = $('Normalizar clientes').first().json;

return clientes.map((cliente) => {
  const doPerfil = produtos.filter((p) => p.perfil === cliente.perfil);
  if (doPerfil.length === 0) {
    throw new Error(`Perfil sem produtos no CSV: ${cliente.perfil}`);
  }

  // O enunciado pede o cruzamento por perfil, mas o CSV tem a coluna 'minimo'.
  // Sem este filtro recomendamos a um cliente com R$ 500 um produto de minimo
  // R$ 1.000, o que e uma recomendacao que ele nao consegue seguir.
  const acessiveis = doPerfil
    .filter((p) => cliente.saldo >= p.minimo)
    .sort((a, b) => (b.minimo - a.minimo) || a.produto.localeCompare(b.produto));
  const excluidos = doPerfil.filter((p) => cliente.saldo < p.minimo);

  const escolhido = acessiveis[0] ?? null;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      saldo_texto: cliente.saldo_texto,
      usar_ia,
      produto_recomendado: escolhido ? escolhido.produto : null,
      rentabilidade: escolhido ? escolhido.rentabilidade : null,
      minimo: escolhido ? escolhido.minimo : null,
      alternativas: acessiveis.slice(1).map((p) => p.produto),
      excluidos_por_saldo: excluidos.map((p) => `${p.produto} (minimo ${p.minimo})`),
      sem_opcao: escolhido === null,
    },
  };
});

// Mensagem estatica por perfil (entregavel do MVP). Fica calculada para todos os
// itens mesmo quando o pedido vai pela IA, para servir de fallback se o LLM falhar.
const textos = {
  Conservador: {
    abertura: 'priorizamos a segurança do seu capital',
    porque: 'privilegia previsibilidade e liquidez, com oscilação baixa',
  },
  Moderado: {
    abertura: 'buscamos um equilíbrio entre segurança e crescimento',
    porque: 'combina a estabilidade da renda fixa com alguma exposição ao crescimento',
  },
  Arrojado: {
    abertura: 'selecionamos uma opção alinhada ao seu apetite por risco',
    porque: 'tem maior potencial de retorno, aceitando oscilações no caminho',
  },
};

const emReais = (valor) => 'R$ ' + Number(valor).toLocaleString('pt-BR');

return $input.all().map((item) => {
  const c = item.json;
  const t = textos[c.perfil] ?? { abertura: 'analisamos o seu perfil', porque: 'é adequado ao seu perfil' };
  const primeiroNome = c.nome.split(' ')[0];

  let mensagem;
  if (c.sem_opcao) {
    mensagem = `Olá ${primeiroNome}, com o saldo atual de ${c.saldo_texto} ainda não há no nosso catálogo uma opção do perfil ${c.perfil} que você possa contratar. Vamos falar com você para encontrar o primeiro passo.`;
  } else {
    const alternativas = c.alternativas.length > 0
      ? ` Como alternativa, você também tem ${c.alternativas.join(' e ')}.`
      : '';
    mensagem = `Olá ${primeiroNome}, ${t.abertura}. Com saldo de ${c.saldo_texto} e perfil ${c.perfil}, nossa sugestão é ${c.produto_recomendado}, com rentabilidade de ${c.rentabilidade}, a partir de ${emReais(c.minimo)}. Escolhemos essa opção porque ${t.porque}.${alternativas} Rentabilidade passada não garante rentabilidade futura.`;
  }

  return { json: { ...c, mensagem_template: mensagem } };
});

